// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line static_invoke_entry.scxml:28
func (p *StaticInvokeEntryPolicy) FirstEnabledTransition(state StaticInvokeEntryState, event StaticInvokeEntryEvent, engine *sce.Engine[StaticInvokeEntryState, StaticInvokeEntryEvent]) (sce.EnabledTransition[StaticInvokeEntryState, sce.HistoryID], bool) {
	switch state {
	case StaticInvokeEntryStateOverflowing:
		if event == StaticInvokeEntryEventErrorExecution {
			{
				return sce.EnabledTransition[StaticInvokeEntryState, sce.HistoryID]{
					Source:          state,
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
		if event == StaticInvokeEntryEventDoneInvokeSecond {
			{
				return sce.EnabledTransition[StaticInvokeEntryState, sce.HistoryID]{
					Source:          state,
					TransitionIndex: 1,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	case StaticInvokeEntryStateRunning:
		if event == StaticInvokeEntryEventHello {
			{
				return sce.EnabledTransition[StaticInvokeEntryState, sce.HistoryID]{
					Source:          state,
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
		if event == StaticInvokeEntryEventDoneInvokeFirst {
			{
				return sce.EnabledTransition[StaticInvokeEntryState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfStaticInvokeEntry[state][1],
					TransitionIndex: 1,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[StaticInvokeEntryState, sce.HistoryID]{}, false
}

